def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_perfect_cube(n):
    if n < 0:
        return False
    root = round(n**(1/3))
    return root**3 == n

def find_solutions(limit):
    solutions = []
    primes = [i for i in range(2, limit + 1) if is_prime(i)]

    print("--- Prime Check Results ---")
    for q in primes:
        N = q*q - q + 1

        # Check if N is a perfect cube
        if is_perfect_cube(N):
            k = round(N**(1/3))

            # Check if k is prime and k != q
            if is_prime(k) and k != q:
                solutions.append((q, k, N))
                print(f"Solution found: q={q}, k={k}, N={N}")
            else:
                print(f"q={q}, N={N} is a perfect cube, but k={k} fails primality or k=q.")
        else:
            print(f"q={q}, N={N} is not a perfect cube.")

    return solutions

# Run check up to 200
solutions = find_solutions(200)
print("\nFinal list of found solutions:", solutions)

